def buyChoco(prices, money):
    prices.sort()
    sum_two = prices[0] + prices[1]
    if sum_two <= money:
        return money - sum_two
    else:
        return money

class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        dp = [0] * n
        dp[0] = nums[0]
        for i in range(1, n):
            dp[i] = (dp[i-1] * 2 + nums[i]) % MOD
        ans = 0
        for i in range(n):
            ans = (ans + dp[i] * dp[i] * nums[i]) % MOD
        return ans

def longest_semi_repetitive_substring(s):
    left = 0
    max_len = 0
    count = 0
    for right in range(len(s)):
        if right > 0 and s[right] == s[right - 1]:
            count += 1
        while count > 1:
            if s[left] == s[left + 1]:
                count -= 1
            left += 1
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len
    return max_len

class Solution:
    def validArray(self, derived: List[int]) -> bool:
        n = len(derived)
        if n == 1:
            return True

        # Check if the first element is 0 or 1
        if derived[0] == 0:
            # If the first element is 0, the last element must be 1
            if derived[-1] == 1:
                return True

        # Check if the first element is 1
        if derived[0] == 1:
            # If the first element is 1, the last element must be 0
            if derived[-1] == 0:
                return True

        # Check if the first two elements are the same
        if derived[0] == derived[1]:
            # If the first two elements are the same, the rest of the array must be the same
            if all(x == derived[0] for x in derived[2:]):
                return True

        return False
