def make_palindrome(s):
    s_list = list(s)
    n = len(s_list)
    for i in range(n // 2):
        left = s_list[i]
        right = s_list[n - 1 - i]
        if left != right:
            s_list[i] = min(left, right)
            s_list[n - 1 - i] = min(left, right)
    return ''.join(s_list)

from math import gcd

class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if gcd(int(str(nums[i])[0]), int(str(nums[j])[-1])) == 1:
                    count += 1
        return count

def min_partition_difference(nums):
    n = len(nums)
    if n == 0:
        return 0

    # Compute prefix_max array
    prefix_max = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_max[i] = max(prefix_max[i-1], nums[i-1])

    # Compute suffix_min array
    suffix_min = [0] * (n + 1)
    suffix_min[n] = nums[-1]
    for i in range(n-1, 0, -1):
        suffix_min[i] = min(nums[i], suffix_min[i+1])

    # Find the minimum difference
    min_diff = float('inf')
    for i in range(1, n):
        current_diff = abs(prefix_max[i] - suffix_min[i])
        if current_diff < min_diff:
            min_diff = current_diff

    return min_diff

def maxJumps(nums, target):
    n = len(nums)
    dp = [-1] * n
    dp[0] = 0  # Starting point

    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= target:
                if dp[j] != -1:
                    if dp[i] < dp[j] + 1:
                        dp[i] = dp[j] + 1

    return dp[-1] if dp[-1] != -1 else -1

def longest_subarray(nums, threshold):
    max_len = 0
    n = len(nums)
    for l in range(n):
        if nums[l] > threshold:
            continue
        current_len = 1
        next_parity = nums[l] % 2
        for r in range(l + 1, n):
            if nums[r] > threshold:
                break
            if nums[r] % 2 == next_parity:
                current_len += 1
                next_parity = 1 - next_parity
            else:
                break
        if current_len > max_len:
            max_len = current_len
    return max_len

class Solution:
    def numSplits(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        count = 0
        one_count = 0
        for i in range(len(nums)):
            if nums[i] == 1:
                one_count += 1
            else:
                if one_count == 1:
                    count += 1
                    one_count = 0
        if one_count == 1:
            count += 1
        return count % MOD

def prime_pairs(n):
    if n < 2:
        return []

    # Sieve of Eratosthenes to find all primes up to n
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])

    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    result = []
    for x in primes:
        if x > n // 2:
            break
        y = n - x
        if y in primes:
            result.append([x, y])

    return result

