class Solution:
    def canMakeAllZero(self, nums, k):
        """
        :type nums: List[int]
        :type k: int
        :rtype: bool
        """
        if k == 1:
            return all(x == 0 for x in nums)

        count = 0
        for i in range(len(nums)):
            if nums[i] > 0:
                count += 1
                if count > k:
                    return False
                nums[i] -= 1
                count -= 1
        return True
