def split_strings(words, separator):
    result = []
    for word in words:
        parts = word.split(separator)
        for part in parts:
            if part:
                result.append(part)
    return result

def finalString(s):
    res = []
    for c in s:
        if c == 'i':
            res = res[::-1]
        else:
            res.append(c)
    return ''.join(res)

class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = max(nums)
        if n > len(nums) + 1:
            return False
        if len(nums) != n + 1:
            return False
        if nums.count(n) != 2:
            return False
        if len(set(nums)) != n:
            return False
        return True

def max_pair_sum(nums):
    from collections import defaultdict

    max_digit_groups = defaultdict(list)

    for num in nums:
        max_d = 0
        while num > 0:
            max_d = max(max_d, num % 10)
            num = num // 10
        max_digit_groups[max_d].append(num)

    max_sum = -1

    for group in max_digit_groups.values():
        if len(group) >= 2:
            sorted_group = sorted(group, reverse=True)
            current_sum = sorted_group[0] + sorted_group[1]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum if max_sum != -1 else -1

def calculate_balance(purchaseAmount):
    rounded = (purchaseAmount + 5) // 10 * 10
    return 100 - rounded

def is_acronym(words, s):
    acronym = ''.join([word[0] for word in words])
    return acronym == s

def count_symmetric(low, high):
    count = 0
    for num in range(low, high + 1):
        s = str(num)
        n = len(s)
        if n % 2 != 0:
            continue
        mid = n // 2
        first = int(s[:mid])
        second = int(s[mid:])
        if first == second:
            count += 1
    return count

class Solution:
    def isPossible(self, str1: str, str2: str) -> bool:
        if len(str1) < len(str2):
            return False

        i = 0
        j = 0

        while i < len(str1) and j < len(str2):
            if str1[i] == str2[j]:
                i += 1
                j += 1
            else:
                if str1[i] == 'z':
                    i += 1
                else:
                    i += 1
                    j += 1

        return j == len(str2)

class Solution:
    def maxFunctionValue(self, receiver, k):
        n = len(receiver)
        dp = [0] * n
        for i in range(n):
            dp[i] = receiver[i]
        for i in range(n):
            if dp[i] == i:
                continue
            dp[i] = i
            for j in range(k):
                dp[i] += receiver[dp[i]]
                if dp[i] == i:
                    break
        return max(dp)
