def countCoveredPoints(nums):
    if not nums:
        return 0
    # Sort the intervals by their start points
    nums.sort(key=lambda x: x[0])
    merged = []
    for interval in nums:
        start, end = interval
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                # Merge the intervals
                new_start = min(start, last_start)
                new_end = max(end, last_end)
                merged[-1] = [new_start, new_end]
            else:
                merged.append(interval)
    # Calculate the total number of covered points
    total = 0
    for s, e in merged:
        total += e - s + 1
    return total

def sum_of_elements_with_k_set_bits(nums, k):
    total = 0
    for i in range(len(nums)):
        if bin(i).count('1') == k:
            total += nums[i]
    return total

def find_beautiful_substring(s, k):
    min_len = float('inf')
    best_sub = ""
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            cnt = substr.count('1')
            if cnt == k:
                current_len = j - i + 1
                if current_len < min_len:
                    min_len = current_len
                    best_sub = substr
                elif current_len == min_len:
                    if substr < best_sub:
                        best_sub = substr
    return best_sub if min_len != float('inf') else ""

class Solution:
    def maxSumOfSquares(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort(reverse=True)
        res = 0
        for i in range(k):
            res += nums[i] * nums[i]
            if i < k - 1:
                res += nums[i] * nums[i]
        return res % MOD

def max_triplet_value(nums):
    max_val = 0
    n = len(nums)
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                current = (nums[i] - nums[j]) * nums[k]
                if current > max_val:
                    max_val = current
    return max_val if max_val >= 0 else 0

def sum_of_squares_of_distinct_counts(nums):
    total = 0
    n = len(nums)
    for i in range(n):
        for j in range(i, n):
            subarray = nums[i:j+1]
            distinct_count = len(set(subarray))
            total += distinct_count ** 2
    return total

class Solution:
    def minGroups(self, nums: List[int]) -> int:
        if not nums:
            return 0

        nums.sort()

        count = 1
        for i in range(1, len(nums)):
            if nums[i] != nums[i - 1]:
                count += 1

        return count

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return -1

        min_sum = float('inf')
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                if nums[i] < nums[j]:
                    for k in range(j + 1, n):
                        if nums[k] < nums[j]:
                            min_sum = min(min_sum, nums[i] + nums[j] + nums[k])

        return min_sum if min_sum != float('inf') else -1

def k_or(nums, k):
    result = 0
    for i in range(31):  # Check up to the 30th bit (since nums[i] < 2^31)
        count = 0
        for num in nums:
            if (num & (1 << i)) != 0:
                count += 1
        if count >= k:
            result |= (1 << i)
    return result

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        max1 = max(nums1)
        max2 = max(nums2)
        if max1 == max2:
            return 0
        if max1 > max2:
            return -1
        if max1 < max2:
            return -1

        if nums1[n-1] == max1 and nums2[n-1] == max2:
            return 0

        if nums1[n-1] == max2 and nums2[n-1] == max1:
            return 1

        if nums1[n-1] == max1 and nums2[n-1] == max1:
            return 1

        if nums1[n-1] == max2 and nums2[n-1] == max2:
            return 1

        if nums1[n-1] == max1 and nums2[n-1] == max2:
            return 2

        if nums1[n-1] == max2 and nums2[n-1] == max1:
            return 2

        if nums1[n-1] == max1 and nums2[n-1] == max1:
            return 2

        if nums1[n-1] == max2 and nums2[n-1] == max2:
            return 2

        return -1

def maximumStrongPairXor(nums):
    max_xor = 0
    n = len(nums)
    for i in range(n):
        for j in range(n):
            x = nums[i]
            y = nums[j]
            if abs(x - y) <= min(x, y):
                current_xor = x ^ y
                if current_xor > max_xor:
                    max_xor = current_xor
    return max_xor

def find_indices(words, x):
    result = []
    for index, word in enumerate(words):
        if x in word:
            result.append(index)
    return result

