class Solution:
    def canMakePalindrome(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        half = n // 2

        def is_palindrome(s):
            return s == s[::-1]

        def can_make_palindrome(a, b, c, d):
            s1 = s[a:b+1]
            s2 = s[c:d+1]
            return is_palindrome(s1) and is_palindrome(s2)

        answer = []
        for a, b, c, d in queries:
            if can_make_palindrome(a, b, c, d):
                answer.append(True)
            else:
                answer.append(False)

        return answer

def count_intersection(nums1, nums2):
    set2 = set(nums2)
    count1 = 0
    for num in nums1:
        if num in set2:
            count1 += 1
    set1 = set(nums1)
    count2 = 0
    for num in nums2:
        if num in set1:
            count2 += 1
    return [count1, count2]

