def countTestedDevices(batteryPercentages):
    count = 0
    n = len(batteryPercentages)
    for i in range(n):
        if batteryPercentages[i] > 0:
            count += 1
            for j in range(i + 1, n):
                batteryPercentages[j] = max(0, batteryPercentages[j] - 1)
    return count

def findPeaks(mountain):
    peaks = []
    n = len(mountain)
    for i in range(1, n - 1):
        if mountain[i] > mountain[i - 1] and mountain[i] > mountain[i + 1]:
            peaks.append(i)
    return peaks

def find_missing_and_duplicate(grid):
    n = len(grid)
    freq = {}
    for row in grid:
        for num in row:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1

    duplicate = None
    for num, count in freq.items():
        if count == 2:
            duplicate = num
            break

    missing = []
    for num in range(1, n * n + 1):
        if num not in freq:
            missing.append(num)
            break

    return [duplicate, missing[0]]

class Solution:
    def maximumSetSize(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()
        i, j = 0, 0
        size = 0
        while i < len(nums1) and j < len(nums2):
            if nums1[i] == nums2[j]:
                size += 1
                i += 1
                j += 1
            elif nums1[i] < nums2[j]:
                i += 1
            else:
                j += 1
        return size

class Solution:
    def maxPartitions(self, s: str, k: int) -> int:
        def get_partitions(s, k):
            partitions = 0
            distinct_chars = set()
            for char in s:
                distinct_chars.add(char)
                if len(distinct_chars) > k:
                    partitions += 1
                    distinct_chars = {char}
            partitions += 1
            return partitions

        max_partitions = get_partitions(s, k)
        for i in range(len(s)):
            new_s = s[:i] + chr(ord(s[i]) + 1) + s[i + 1:]
            max_partitions = max(max_partitions, get_partitions(new_s, k))
        return max_partitions

class Solution:
    def smallestMissingInteger(self, nums: List[int]) -> int:
        if not nums:
            return 1

        longest_prefix_sum = nums[0]
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1] + 1:
                longest_prefix_sum += nums[i]
            else:
                break

        for i in range(longest_prefix_sum, len(nums) + 1):
            if i not in nums:
                return i

def maxFrequency(nums):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1
    max_freq = max(freq.values())
    total = 0
    for v in freq.values():
        if v == max_freq:
            total += v
    return total

