def minCost(nums):
    n = len(nums)
    min_cost = float('inf')
    for i in range(n - 2):
        for j in range(i + 1, n):
            part1 = nums[:i+1]
            part2 = nums[i+1:j+1]
            part3 = nums[j+1:]
            current_cost = part1[0] + part2[0] + part3[0]
            if current_cost < min_cost:
                min_cost = current_cost
    return min_cost

