    N, M = map(int, sys.stdin.readline().split())
    S = [sys.stdin.readline().strip() for _ in range(N)]

    def is_valid(T):
        for i in range(N-1):
            if T[i] != T[i+1]:
                if T[i] == T[i+1]:
                    return False
                else:
                    return True
        return True

    def dfs(S, T):
        if len(S) == 1:
            return is_valid(T)

        for i in range(len(S)):
            for j in range(len(S)):
                if i != j:
                    S1, S2 = S[:i], S[i:]
                    T1, T2 = T[:j], T[j:]
                    if dfs(S1, T1) and dfs(S2, T2):
                        return True
        return False

    if dfs(S, []):
        print("Yes")
    else:
        print("No")

