def min_time_to_type(X, Y, Z, S):
    n = len(S)
    dp = [[float('inf')] * 2 for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(2):
            if j == 0:
                dp[i][j] = min(dp[i - 1][j] + X, dp[i - 1][j] + Y)
            else:
                dp[i][j] = min(dp[i - 1][j] + X, dp[i - 1][j] + Y)
            dp[i][j] = min(dp[i][j], dp[i - 1][1 - j] + Z)

    return min(dp[n][0], dp[n][1])

