def find_route(cities_to_visit, landmarks):
    # Create a dictionary to store the index of each city in the cities_to_visit list
    city_index = {city: i for i, city in enumerate(cities_to_visit)}

    # Create a list to store the order of cities to visit
    route = []

    # Iterate over the landmarks list
    for landmark in landmarks:
        # If the landmark is not in the cities_to_visit list, add it to the route
        if landmark not in city_index:
            route.append(landmark)

        # If the landmark is in the cities_to_visit list, find its index
        else:
            index = city_index[landmark]

            # If the index is greater than the current index in the route, add the landmark to the route
            if index > route[-1]:
                route.append(landmark)

    # Add the last city in the cities_to_visit list to the route
    route.append(cities_to_visit[-1])

    return route

