    dp = [[0] * (X + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(X + 1):
            for k in range(i):
                if j + T[k] <= X:
                    dp[i][j + T[k]] += dp[k][j]
                    dp[i][j + T[k]] %= MOD

    ans = 0
    for j in range(X + 1):
        ans += dp[N][j] * modinv(N, MOD)
        ans %= MOD

    print(ans)

