                return False
        return True

    def is_delete(s, t):
        if len(s) != len(t):
            return False
        for i in range(len(s)):
            if s[i] != t[i]:
                return False
        return True

    def is_change(s, t):
        if len(s) != len(t):
            return False
        for i in range(len(s)):
            if s[i] != t[i]:
