def min_coins_for_trip(n, m, c, friends_money):
    total_money = sum(friends_money)
    if total_money % n != 0:
        return -1

    fair_share = total_money // n
    coins_needed = 0

    for money in friends_money:
        coins_needed += (money - fair_share) // c
        if coins_needed > m:
            return -1

    return coins_needed

