def min_coins(n, c, cost):
    coins = sorted(c, reverse=True)
    remaining_cost = cost
    coins_used = 0

    for coin in coins:
        if remaining_cost <= 0:
            break
        if remaining_cost >= coin:
            remaining_cost -= coin
            coins_used += 1
        else:
            remaining_cost -= coin
            coins_used += 1

    return coins_used

