from typing import List

def min_groups(favorite_numbers: List[int], k: int) -> List[List[int]]:
    favorite_numbers.sort()
    groups = []
    current_group = []
    group_count = 0

    for num in favorite_numbers:
        if not current_group or num != current_group[-1]:
            current_group.append(num)
        else:
            if group_count < k:
                groups.append(current_group)
                current_group = [num]
                group_count += 1
            else:
                return []

    if group_count < k:
        groups.append(current_group)

    return groups

