def is_palindrome(n):
    s = str(n)
    return s == s[::-1]

def cube_root(n):
    low = 1
    high = n
    while low <= high:
        mid = (low + high) // 2
        mid_cube = mid * mid * mid
        if mid_cube == n:
            return mid
        elif mid_cube < n:
            low = mid + 1
        else:
            high = mid - 1
    return -1

