import sys

def main():
    N, H, W = map(int, sys.stdin.readline().split())
    tiles = []
    for _ in range(N):
        A, B = map(int, sys.stdin.readline().split())
        tiles.append((A, B))

    def can_place(x, y, a, b):
        if x + a > H or y + b > W:
            return False
        for i in range(a):
            for j in range(b):
                if tiles[0][0] > 1 or tiles[0][1] > 1:
                    return False
        return True

    def place(x, y, a, b):
        for i in range(a):
            for j in range(b):
                tiles[0][0] -= 1
                tiles[0][1] -= 1
                sys.stdout.write('.')
                sys.stdout.flush()
        sys.stdout.write('\n')
        sys.stdout.flush()

    def remove(x, y, a, b):
        for i in range(a):
            for j in range(b):
                tiles[0][0] += 1
                tiles[0][1] += 1
                sys.stdout.write('.')
                sys.stdout.flush()
        sys.stdout.write('\n')
        sys.stdout.flush()

    def backtrack(x, y, a, b):
        if x + a > H or y + b > W:
            return False
        for i in range(a):
            for j in range(b):
                if tiles[0][0] > 1 or tiles[0][1] > 1:
                    return False
        return True

    def solve():
        if backtrack(0, 0, N, 1):
            return True

        for i in range(N):
            if can_place(0, 0, tiles[i][0], tiles[i][1]):
                place(0, 0, tiles[i][0], tiles[i][1])
                if solve():
                    return True
                remove(0, 0, tiles[i][0], tiles[i][1])

        return False

    if solve():
        print("Yes")
    else:
        print("No")

