def min_x(a, C):
    n = len(a)
    low = min(a)
    high = C // n
    while low < high:
        mid = (low + high) // 2
        if can_split(a, C, mid):
            high = mid
        else:
            low = mid + 1
    return low

def can_split(a, C, x):
    total = 0
    for i in range(n):
        if a[i] < x:
            return False
        total += a[i]
    return total >= C

