def tsp(distances):
    n = len(distances)
    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    dp[1][1] = 0

    for subset in range(1, 1 << n):
        for city in range(n):
            if subset & (1 << city):
                for ending_city in range(n):
                    if not (subset & (1 << ending_city)):
                        dp[subset][ending_city] = min(dp[subset][ending_city], dp[subset ^ (1 << city)][city] + distances[city][ending_city])

    return dp[2**n - 1][1]

def find_shortest_route(distances):
    n = len(distances)
    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    dp[1][1] = 0

    for subset in range(1, 1 << n):
        for city in range(n):
            if subset & (1 << city):
                for ending_city in range(n):
                    if not (subset & (1 << ending_city)):
                        dp[subset][ending_city] = min(dp[subset][ending_city], dp[subset ^ (1 << city)][city] + distances[city][ending_city])

    # Backtrack to find the shortest route
    route = []
    current_city = 1
    for _ in range(n - 1):
        route.append(current_city)
        for ending_city in range(n):
            if dp[2**n - 1][ending_city] == dp[2**n - 1][current_city] + distances[current_city][ending_city]:
                current_city = ending_city
                break

    route.append(1)
    return route

