def max_prime_distance(nums):
    # Sieve of Eratosthenes to find primes up to 100
    sieve = [True] * 101
    sieve[0] = sieve[1] = False
    for i in range(2, int(100**0.5) + 1):
        if sieve[i]:
            sieve[i*i : 100+1 : i] = [False] * len(sieve[i*i : 100+1 : i])

    # Collect indices of primes
    primes = []
    for idx, num in enumerate(nums):
        if sieve[num]:
            primes.append(idx)

    # If there are less than two primes, return 0
    if len(primes) < 2:
        return 0
    else:
        primes.sort()
        return primes[-1] - primes[0]

def shortest_special_subarray(nums, k):
    n = len(nums)
    for i in range(n):
        current_or = 0
        for j in range(i, n):
            current_or |= nums[j]
            if current_or >= k:
                return j - i + 1
    return -1

class Solution:
    def sumOfPowers(self, nums, k):
        MOD = 10**9 + 7
        n = len(nums)
        dp = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = 0
        for i in range(n):
            for j in range(i + 1, n):
                dp[i][j] = min(dp[i][j], abs(nums[i] - nums[j]))
        ans = 0
        for i in range(n - k + 1):
            for j in range(i + 1, n - k + 1):
                ans += dp[i][j]
                ans %= MOD
        return ans
