def score_of_string(s):
    score = 0
    for i in range(len(s) - 1):
        diff = abs(ord(s[i]) - ord(s[i + 1]))
        score += diff
    return score

class Solution:
    def findMedianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        count = [0] * (n + 1)
        for i in range(n):
            count[nums[i]] += 1
        for i in range(n):
            count[nums[i]] -= 1
        count = [0] + count
        count.sort()
        return count[n // 2]
