    n = len(nums)
    count = {}
    for i in range(n):
        if nums[i] in count:
            count[nums[i]] += 1
        else:
            count[nums[i]] = 1
    count = [0] + list(count.values())
    count.sort()
    return count[n // 2]

class Solution:
    def minCost(self, nums: List[int], cost1: int, cost2: int) -> int:
        n = len(nums)
        if n == 1:
            return 0
        if n == 2:
            return min(cost1, cost2)

        nums.sort()

        dp = [0] * n
        dp[0] = nums[0]
        dp[1] = nums[1]

        for i in range(2, n):
            dp[i] = min(dp[i-1] + cost1, dp[i-2] + cost2)

        return dp[-1]
