def count_good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            product = nums2[j] * k
            if nums1[i] % product == 0:
                count += 1
    return count

def compress(word):
    comp = []
    if not word:
        return comp
    current_char = word[0]
    count = 1
    for c in word[1:]:
        if c == current_char:
            count += 1
        else:
            comp.append(f"{min(count, 9)} {current_char}")
            current_char = c
            count = 1
    # Add the last run
    comp.append(f"{min(count, 9)} {current_char}")
    return ''.join(comp)

class Solution:
    def maxSumNonAdjacent(self, nums):
        if not nums:
            return 0
        if len(nums) == 1:
            return max(0, nums[0])
        dp = [0] * len(nums)
        dp[0] = max(0, nums[0])
        dp[1] = max(dp[0], nums[1])
        for i in range(2, len(nums)):
            dp[i] = max(dp[i - 1], dp[i - 2] + nums[i])
        return dp[-1]

    def rangeSum(self, nums, queries):
        ans = 0
        for pos, x in queries:
            nums[pos] = x
            ans += self.maxSumNonAdjacent(nums)
        return ans % (10**9 + 7)
