class Solution:
    def productQueries(self, queries: List[List[int]]) -> List[int]:
        def get_power_of_two(n):
            if n == 0:
                return 1
            return 2 ** (n - 1)

        def get_power_of_two_array(n):
            return [get_power_of_two(i) for i in range(n)]

        def get_powerful_array(n):
            result = []
            i = 0
            while n > 0:
                if n & 1:
                    result.append(get_power_of_two(i))
                n >>= 1
                i += 1
            return result

        def get_big_nums(n):
            result = []
            i = 0
            while n > 0:
                result.extend(get_powerful_array(i))
                n >>= 1
                i += 1
            return result

        def get_product(start, end):
            result = 1
            for i in range(start, end + 1):
                result *= get_big_nums(i)[i - start]
            return result

        answer = []
        for query in queries:
            start, end, mod = query
            product = get_product(start, end)
            answer.append(product % mod)
        return answer
