from collections import Counter

def xor_of_duplicates(nums):
    count = Counter(nums)
    result = 0
    for num, cnt in count.items():
        if cnt == 2:
            result ^= num
    return result

def find_occurrences(nums, queries, x):
    pos = []
    for idx, num in enumerate(nums):
        if num == x:
            pos.append(idx)
    answer = []
    for q in queries:
        if q <= len(pos):
            answer.append(pos[q-1])
        else:
            answer.append(-1)
    return answer
